package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;

/** A person on a sheet. {@code grades} are their grades (each one of A, B or C) by the date each applies
 *  from, the first from {@link #START} (the beginning of time); {@code version} moves on with each stored edit;
 *  {@code retiredFrom} is the date they are retired from (null while not retired); {@code pastRetirements}
 *  the retirements they were unretired from, oldest first; {@code holds} their holds,
 *  oldest first: their OPEN claims dated within one count in no live total unless a statement bound them, nor do
 *  any of their OPEN claims once the sheet's today reaches their retirement date. */
public class Person {
    /** The from-date of a person's first grade: the beginning of time. */
    public static final LocalDate START = LocalDate.of(1, 1, 1);

    private final long id;
    private final String sheetId;
    private String name;
    private final NavigableMap<LocalDate, String> grades;
    private long version;
    private LocalDate retiredFrom;
    private final List<Hold> holds = new ArrayList<>();
    private final List<PastRetirement> pastRetirements = new ArrayList<>();
    private final List<String> aliases = new ArrayList<>();
    private LocalDate recordFrom;
    private Integer terms;
    private boolean termsChanged;
    private String contact;
    private boolean contactChanged;
    private String origin;

    public Person(long id, String sheetId, String name, NavigableMap<LocalDate, String> grades, long version) {
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        this.grades = new TreeMap<>(grades);
        this.version = version;
    }

    public Person(long id, String sheetId, String name, NavigableMap<LocalDate, String> grades, long version,
            LocalDate retiredFrom, List<Hold> holds) {
        this(id, sheetId, name, grades, version);
        this.retiredFrom = retiredFrom;
        this.holds.addAll(holds);
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public String getName() { return name; }
    /** The grade in force on the date: the one with the latest from-date on or before it. */
    public String gradeOn(LocalDate on) {
        Map.Entry<LocalDate, String> e = grades.floorEntry(on);
        return e == null ? grades.firstEntry().getValue() : e.getValue();
    }
    /** Every grade by the date it applies from ({@link #START} for the first). */
    public NavigableMap<LocalDate, String> getGrades() { return grades; }
    /** The from-date of the grade the next save records, null when it records none. */
    public LocalDate getRecordFrom() { return recordFrom; }
    public long getVersion() { return version; }
    public LocalDate getRetiredFrom() { return retiredFrom; }
    /** Retired as soon as a date is set, whatever the date. */
    public boolean isRetired() { return retiredFrom != null; }
    /** Whether their retirement date is reached on the date: from then their OPEN (and PENDING) claims count
     *  in no live total unless a statement bound them, as a hold's would. */
    public boolean retiredOn(LocalDate date) { return retiredFrom != null && date != null && !date.isBefore(retiredFrom); }
    /** Whether the person has any hold, whatever its dates. */
    public boolean isHeld() { return !holds.isEmpty(); }
    /** Their holds, oldest first. */
    public List<Hold> getHolds() { return holds; }
    /** Whether a hold of theirs covers the date. */
    public boolean heldOn(LocalDate date) { return holds.stream().anyMatch(h -> h.covers(date)); }
    public void addHold(Hold hold) { holds.add(hold); }
    /** Their aliases: other names they are found by, sorted as names are compared. */
    public List<String> getAliases() { return aliases; }
    public void setName(String name) { this.name = name; }
    /** Records the grade from the date at the next save, keeping the others. */
    public void recordGrade(LocalDate from, String grade) {
        grades.put(from, grade);
        recordFrom = from;
    }
    /** Their own terms (whole days), null when they have none. */
    public Integer getTerms() { return terms; }
    /** Sets their own terms, noting whether they differ from the ones they had. */
    public void setTerms(Integer terms) {
        termsChanged = !java.util.Objects.equals(this.terms, terms);
        this.terms = terms;
    }
    /** Whether the last {@link #setTerms} changed their terms. */
    public boolean isTermsChanged() { return termsChanged; }
    /** Their contact (trimmed, lower-cased), null when they have none. */
    public String getContact() { return contact; }
    /** Sets their contact, noting whether it differs from the one they had. */
    public void setContact(String contact) {
        contactChanged = !java.util.Objects.equals(this.contact, contact);
        this.contact = contact;
    }
    /** Whether the last {@link #setContact} changed their contact. */
    public boolean isContactChanged() { return contactChanged; }
    /** The sheet they were transferred from, null when they were not transferred here. */
    public String getOrigin() { return origin; }
    public void setOrigin(String origin) { this.origin = origin; }
    public void setVersion(long version) { this.version = version; }
    public void setRetiredFrom(LocalDate retiredFrom) { this.retiredFrom = retiredFrom; }
    /** Their past retirements (each ended by unretiring them), oldest first. */
    public List<PastRetirement> getPastRetirements() { return pastRetirements; }
}
package net.officefloor.hq.app.person;

/**
 * Body of a person add or edit: the name, the grade (A, B or C), the date (yyyy-MM-dd) an edit
 * records the grade from (blank for the sheet's today; an add's grade applies from the beginning of
 * time) and who makes the change. An edit also carries the version of the person its editor loaded
 * (none for an add). {@code terms} are the person's own terms in whole days, blank (null) for none.
 * {@code contact} is their contact, trimmed and lower-cased, blank (null) for none.
 */
public record PersonRequest(String name, String grade, String gradeFrom, String user, Long version, String terms, String contact) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.statement.StatementSummary;

/** A person as the front end reads it: the grade in force on the sheet's today and every grade with the
 *  date (yyyy-MM-dd) it applies from (null for the first, from the beginning of time), with their
 *  statement count and the last statement's due-total and date (null when none was taken), whether they
 *  are retired and from when (null when not) and whether the sheet's today has reached that date, whether they have any hold
 *  and each hold's from-date and to-date (null for no end), the ids of their patrons (in the order named), and their own terms
 *  (whole days, null when none), their contact (null when none) and their aliases, sorted as names are compared, and whether they clash: their
 *  name or an alias is used as a name or alias on another sheet of the sheet's tree, and the sheet they were
 *  transferred from (null when they were not), and their past retirements, oldest first. */
public record PersonResponse(long id, String name, String grade, List<GradeFrom> grades, long version,
        int statementCount, String statedTotal, String statementDate, boolean retired, String retiredFrom,
        boolean held, List<HoldFrom> holds, List<Long> patronIds, Integer terms,
        boolean retiredNow, String contact, List<String> aliases, boolean clashing,
        String origin, List<RetirementFrom> pastRetirements) {

    /** A past retirement's from-date and to-date, the day they were unretired (yyyy-MM-dd). */
    public record RetirementFrom(String from, String to) {
    }

    /** A hold's from-date and to-date (yyyy-MM-dd; null for no end). */
    public record HoldFrom(String from, String to) {
    }

    /** A grade and the date it applies from (null for from the beginning of time). */
    public record GradeFrom(String grade, String from) {
    }

    public static PersonResponse from(Person p, LocalDate today, StatementSummary s, List<Long> patronIds,
            boolean clashing) {
        List<GradeFrom> grades = p.getGrades().entrySet().stream()
                .map(e -> new GradeFrom(e.getValue(), Person.START.equals(e.getKey()) ? null : e.getKey().toString()))
                .toList();
        return new PersonResponse(p.getId(), p.getName(), p.gradeOn(today), grades, p.getVersion(), s.count(),
                s.lastDueTotal(), s.lastDate(), p.isRetired(),
                p.getRetiredFrom() == null ? null : p.getRetiredFrom().toString(), p.isHeld(),
                p.getHolds().stream().map(h -> new HoldFrom(h.from().toString(), h.to() == null ? null : h.to().toString()))
                        .toList(),
                patronIds, p.getTerms(), p.retiredOn(today), p.getContact(),
                List.copyOf(p.getAliases()), clashing, p.getOrigin(),
                p.getPastRetirements().stream().map(r -> new RetirementFrom(r.from().toString(), r.to().toString()))
                        .toList());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Val;

/** Applies an edit: the name, and the form's grade recorded from its from-date (the sheet's today when
 *  blank), keeping the grades already recorded — except that a grade left as the row showed it (the one
 *  in force on the sheet's today) with the from-date blank records nothing. Their own terms and contact become the form's
 *  (none when blank). */
public class ApplyPerson {
    public void apply(@Val PersonRequest request, @Val Person person, SheetStore sheets) {
        person.setName(request.name());
        person.setContact(request.contact());
        person.setTerms(request.terms() == null ? null : Integer.valueOf(request.terms()));
        PersonRules.applyGrade(person, request.grade(), request.gradeFrom(), sheets.today(person.getSheetId()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class SavePersonAdded {
    public void save(@PathVariable("sheetId") String sheetId, @Val PersonRequest request, PersonStore store,
            Out<Person> person) {
        person.set(store.add(sheetId.trim(), request.name(), request.grade(),
                request.terms() == null ? null : Integer.valueOf(request.terms()), request.contact()));
    }
}
-- A person's contact: stored trimmed and lower-cased, null when they have none. No two people on a sheet
-- share one. Kept in person_hist too; the history trigger is set again afterwards, as in V45__claim_tags.sql.
DROP TRIGGER person_history;
ALTER TABLE person ADD COLUMN contact VARCHAR(255);
ALTER TABLE person_hist ADD COLUMN contact VARCHAR(255);
CREATE UNIQUE INDEX person_sheet_contact ON person (sheet_id, contact);
CREATE TRIGGER person_history AFTER INSERT, UPDATE, DELETE ON person FOR EACH ROW
    CALL 'net.officefloor.hq.app.history.HistoryTrigger';
-- A claim's tags: each trimmed and lower-cased, repeats dropped, sorted and comma separated (no spaces);
-- null when it has none. A claim split off another carries the original's. Kept in claim_hist too (see
-- V39__history.sql); the history trigger is set again afterwards, as in V41__claim_reminded.sql.
DROP TRIGGER claim_history;
ALTER TABLE claim ADD COLUMN tags VARCHAR(4000);
ALTER TABLE claim_hist ADD COLUMN tags VARCHAR(4000);
CREATE TRIGGER claim_history AFTER INSERT, UPDATE, DELETE ON claim FOR EACH ROW
    CALL 'net.officefloor.hq.app.history.HistoryTrigger';

